parameters.jsCode:
const rawInput = $input.item.json.sparqlQuery || $input.item.json.output;
if (!rawInput || typeof rawInput !== 'string') {
  throw new Error('Expected a SPARQL query string');
}

let sparql = rawInput.replace(/```sparql|```/gi, '').trim();

const requiredPrefixes = [
  'PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>',
  'PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>',
  'PREFIX cpl: <https://example.org/cpl#>',
  'PREFIX prov: <http://www.w3.org/ns/prov#>'
];

for (const prefix of requiredPrefixes.reverse()) {
  const name = prefix.match(/^PREFIX\s+(\w+):/i)[1].toLowerCase();
  if (!new RegExp(`^PREFIX\\s+${name}:`, 'im').test(sparql)) {
    sparql = `${prefix}\n${sparql}`;
  }
}

sparql = sparql.replace(
  /"([^"]*?)"\^\^<http:\/\/www\.w3\.org\/2001\/XMLSchema#(string|dateTime|float)>/g,
  (_, value, type) => `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"^^xsd:${type}`
);

return { json: { sparqlQuery: sparql, telemetry: $input.item.json.telemetry || null } };

const current = $input.item.json || {};
const evidence = $node["Attach Static Ontology Contract"]?.json || {};
const evidenceId = evidence.evidence_id || current.evidence_id || null;
const evidenceRef = evidenceId ? `urn:cpl:evidence:${evidenceId}` : null;
const originalPayload = evidence.raw_payload ?? current.raw_payload ?? null;
const ingestTimestamp = evidence.ingest_timestamp || null;

function baseFailure(message, rawOutput) {
  return {
    json: {
      timestamp: null,
      actor: null,
      target: null,
      tool: null,
      accessed_data: null,
      target_agent: null,
      job: null,
      severity: null,
      duration_ms: null,
      relationships: [],
      attributes: { evidence_id: evidenceId },
      context_summary: null,
      confidence: null,
      raw: originalPayload,
      raw_llm_output: rawOutput || null,
      raw_payload: originalPayload,
      evidence_id: evidenceId,
      ingest_timestamp: ingestTimestamp,
      kafka_topic: evidence.kafka_topic || null,
      kafka_partition: evidence.kafka_partition ?? null,
      kafka_offset: evidence.kafka_offset ?? null,
      "prov:wasDerivedFrom": evidenceRef,
      prov_wasDerivedFrom: evidenceRef,
      parseError: true,
      error_message: message,
      failed_stage: 'json_parse'
    }
  };
}

let raw = current.output;
if (!raw || typeof raw !== 'string') {
  return baseFailure('Telemetry Collector Agent did not return a JSON string', raw);
}

raw = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();

let input;
try {
  input = JSON.parse(raw);
} catch (error) {
  return baseFailure(`JSON.parse failed: ${error.message}`, raw);
}

if (!input.timestamp) {
  return baseFailure('Missing required timestamp; strict mode does not substitute ingest time', raw);
}

let timestamp;
try {
  timestamp = new Date(input.timestamp).toISOString();
  if (timestamp === 'Invalid Date') throw new Error('Invalid Date');
} catch (error) {
  return baseFailure(`Invalid timestamp: ${input.timestamp}`, raw);
}

const actorId = typeof input.actor === 'string' ? input.actor : input.actor?.id || null;
const targetId = typeof input.target === 'string' ? input.target : input.target?.id || null;
const attributes = input.attributes && typeof input.attributes === 'object' && !Array.isArray(input.attributes) ? input.attributes : {};
attributes.evidence_id = evidenceId;

const tool = input.tool || attributes.tool || attributes.used_tool || attributes.tool_id || null;
const accessedData = input.accessed_data || attributes.accessed_data || attributes.data_entity || attributes.data || null;
const targetAgent = input.target_agent || attributes.target_agent || (targetId && !accessedData ? targetId : null);

return {
  json: {
    timestamp,
    actor: actorId ? {
      type: typeof input.actor === 'object' ? input.actor?.type || 'agent' : 'agent',
      id: actorId
    } : null,
    target: targetId ? {
      type: typeof input.target === 'object' ? input.target?.type || 'entity' : 'entity',
      id: targetId
    } : null,
    tool,
    accessed_data: accessedData,
    target_agent: targetAgent,
    job: input.job || null,
    severity: input.severity || null,
    duration_ms: input.duration_ms != null ? Number(input.duration_ms) : null,
    relationships: (input.relationships || []).map(r => {
      if (typeof r === 'string') {
        const [source, type, target] = r.split(' → ');
        return { source, type, target };
      }
      return r;
    }),
    attributes,
    context_summary: input.context_summary || null,
    confidence: input.confidence != null ? Number(input.confidence) : null,
    raw: input.raw || originalPayload,
    raw_payload: originalPayload,
    evidence_id: evidenceId,
    ingest_timestamp: ingestTimestamp,
    kafka_topic: evidence.kafka_topic || null,
    kafka_partition: evidence.kafka_partition ?? null,
    kafka_offset: evidence.kafka_offset ?? null,
    "prov:wasDerivedFrom": evidenceRef,
    prov_wasDerivedFrom: evidenceRef,
    parseError: input.parseError === true,
    error_message: input.parseError === true ? (input.error_message || 'Extractor marked record as parseError') : null
  }
};

if ($json.ontology && $json.mapping && $json.telemetry) {
  return $json;
}

if (!$json.output || typeof $json.output !== 'string') {
  throw new Error('Expected static ontology mapping object or JSON output string');
}

const str = $json.output.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
return JSON.parse(str);

const telemetry = $json.telemetry || $json;
const CPL = 'https://example.org/cpl#';

function esc(value) {
  return String(value ?? '').replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function local(value, fallback) {
  return String(value || fallback || 'unknown').replace(/[^A-Za-z0-9_\-]/g, '_');
}

const evidenceId = telemetry.evidence_id;
const actionId = local(`action_${evidenceId}`);
const agentId = local(telemetry.actor?.id, 'agent_unknown');
const toolId = local(telemetry.tool, 'tool_unknown');
const dataId = local(telemetry.accessed_data, 'data_unknown');
const evidenceIri = `urn:cpl:evidence:${esc(evidenceId)}`;
const rawPayload = JSON.stringify(telemetry.raw_payload ?? telemetry.raw ?? {});

const sparqlQuery = `PREFIX cpl: <${CPL}>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

INSERT DATA {
  GRAPH <urn:cpl:assertions> {
    cpl:${actionId} a cpl:AgentAction ;
      cpl:performedBy cpl:${agentId} ;
      cpl:usedTool cpl:${toolId} ;
      cpl:accessedData cpl:${dataId} ;
      cpl:timestamp "${esc(telemetry.timestamp)}"^^xsd:dateTime ;
      prov:wasDerivedFrom <${evidenceIri}> .

    cpl:${agentId} a cpl:Agent ; cpl:agentId "${esc(telemetry.actor?.id)}" .
    cpl:${toolId} a cpl:Tool ; cpl:toolId "${esc(telemetry.tool)}" .
    cpl:${dataId} a cpl:DataEntity ; cpl:dataId "${esc(telemetry.accessed_data)}" .
    <${evidenceIri}> a cpl:EvidenceEvent ;
      cpl:evidenceId "${esc(evidenceId)}" ;
      cpl:ingestTimestamp "${esc(telemetry.ingest_timestamp)}"^^xsd:dateTime ;
      cpl:rawPayload "${esc(rawPayload)}" .
  }
}`;

return { json: { sparqlQuery, telemetry } };

const telemetry = $input.item.json;

return {
  json: {
    ontology: {
      source: 'ontology/cpl-ontology.ttl',
      classes: ['cpl:Agent', 'cpl:Tool', 'cpl:AgentAction', 'cpl:DataEntity', 'cpl:EvidenceEvent'],
      properties: ['cpl:performedBy', 'cpl:usedTool', 'cpl:accessedData', 'cpl:timestamp', 'prov:wasDerivedFrom']
    },
    mapping: {
      action: 'cpl:AgentAction',
      actor: 'cpl:performedBy',
      tool: 'cpl:usedTool',
      accessed_data: 'cpl:accessedData',
      timestamp: 'cpl:timestamp',
      evidence: 'prov:wasDerivedFrom'
    },
    telemetry
  }
};

// n8n Function Node
const item = $json; // single telemetry item

let actor = null;
let target = null;
let job = "context_processing_layer";
let latencyMs = 0;
let message = item.message || item._id || null;
let severity = item.severity || null;
let error_code = item.error_code || null;
let data_size_kb = typeof item.data_size_kb === "number" ? item.data_size_kb : null;

// Use timestamps if available
const now = Date.now();
const eventTime = item.timestamp ? new Date(item.timestamp).getTime() : now;
latencyMs = Math.max(now - eventTime, 0);

// Attempt to extract actor and target from RDF-like fields
for (const key in item) {
    if (!item[key] || typeof item[key] !== "string") continue;
    const value = item[key];

    // Actor
    const actorMatch = value.match(/hasActor>\s*<[^#]+#([^>]+)>|isActorOf>\s*<[^#]+#([^>]+)>/i);
    if (actorMatch) actor = actorMatch[1] || actorMatch[2];

    // Target
    const targetMatch = value.match(/hasTarget>\s*<[^#]+#([^>]+)>|isTargetOf>\s*<[^#]+#([^>]+)>/i);
    if (targetMatch) target = targetMatch[1] || targetMatch[2];

    // Latency override if specified
    const latencyMatch = value.match(/hasDuration(Ms|Milliseconds)>\s*"(\d+)"/i);
    if (latencyMatch) latencyMs = parseInt(latencyMatch[2]);

    // Severity
    const severityMatch = value.match(/hasSeverity>\s*(?:<[^#]+#([^>]+)>|"([^"]+)")/i);
    if (severityMatch) severity = severityMatch[1] || severityMatch[2];

    // Error code
    const errorCodeMatch = value.match(/hasErrorCode>\s*(?:<[^#]+#([^>]+)>|"([^"]+)")/i);
    if (errorCodeMatch) error_code = errorCodeMatch[1] || errorCodeMatch[2];

    // Data size
    const dataSizeMatch = value.match(/hasDataSize(Kb|Kilobytes)>\s*"(\d+)"/i);
    if (dataSizeMatch) data_size_kb = parseInt(dataSizeMatch[2]);
}

// Fallback: parse actor/target from context summary
if ((!actor || !target) && item.context_summary) {
    const summaryMatch = item.context_summary.match(/Agent ['"]?([^'"]+)['"]?.*?with ['"]?([^'"\s]+)['"]?/ims);
    if (summaryMatch) {
        actor = actor || summaryMatch[1];
        target = target || summaryMatch[2];
    }
}

// Transform success if actor and target exist
const transformSuccess = actor && target ? 1 : 0;
const errorCount = transformSuccess ? 0 : 1;
const status = transformSuccess ? "success" : "failed";

// Return standardized output
return {
    timestamp: eventTime,
    ingestTimestamp: now,
    totalCount: 1,
    ingestCount: 1,
    transformSuccess,
    errorCount,
    latencyMs,
    trace_id: item.trace_id || null,
    job,
    actor: actor || "unknown",
    target: target || "unknown",
    region: item.region || null,
    host: item.host || null,
    message,
    severity,
    status,
    error_code,
    data_size_kb
};

// Access the current input item
const item = $input.item;

// Extract the output object
const data = item.json || {};

// Use ingestTimestamp or fallback to now
const ingestTime = data.ingestTimestamp ? new Date(data.ingestTimestamp).getTime() : Date.now();

// Use event timestamp if available, else fallback to ingestTime
const eventTime = data.timestamp ? new Date(data.timestamp).getTime() : ingestTime;

// Calculate latency in ms (ingestTime - eventTime)
const latencyMs = Math.max(ingestTime - eventTime, 0); // avoid negative

// Convert timestamp to nanoseconds for Loki
const ts_ns = String(ingestTime * 1e6);

// Build the Loki push payload
return {
  streams: [
    {
      stream: {
        job: data.job || "context_processing_layer",
        actor: data.actor || "unknown",
        target: data.target || "unknown",
        region: data.region || "unknown",
        host: data.host || "unknown",

        // Metric labels
        ingestCount: String(data.ingestCount ?? "0"),
        transformSuccess: String(data.transformSuccess ?? "0"),
        totalCount: String(data.totalCount ?? "0"),
        errorCount: String(data.errorCount ?? "0"),
        latencyMs: String(latencyMs)   // <-- dynamically calculated
      },
      values: [
        [ts_ns, data.message || data.id || "No message"]
      ]
    }
  ]
};

function uuidv4() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') {
    return globalThis.crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const event = $input.item.json || {};
const rawPayload = event.message && typeof event.message === 'object' ? event.message : event;
const evidenceId = uuidv4();
const ingestTimestamp = new Date().toISOString();

return {
  json: {
    evidence_id: evidenceId,
    raw_payload: rawPayload,
    ingest_timestamp: ingestTimestamp,
    kafka_topic: event.topic || event.kafka_topic || event.topicName || 'context-processing-layer-trigger-topic',
    kafka_partition: event.partition ?? event.kafka_partition ?? null,
    kafka_offset: event.offset ?? event.kafka_offset ?? null
  }
};

const prepared = $node["Prepare Raw Evidence"]?.json || $input.item.json || {};
const item = { ...prepared };

item.ontology_contract = `Static CPL ontology contract from ontology/cpl-ontology.ttl:
Classes: cpl:Agent, cpl:Tool, cpl:AgentAction, cpl:DataEntity, cpl:EvidenceEvent.
Required AgentAction properties: cpl:performedBy (Agent), cpl:usedTool (Tool), cpl:accessedData (DataEntity), cpl:timestamp (xsd:dateTime), prov:wasDerivedFrom (EvidenceEvent).
Required entity identifiers: cpl:agentId for Agent, cpl:toolId for Tool, cpl:dataId for DataEntity, cpl:evidenceId plus cpl:ingestTimestamp for EvidenceEvent.
Allowed top-level JSON fields: timestamp, actor, target, tool, accessed_data, target_agent, job, severity, duration_ms, relationships, attributes, context_summary, confidence, raw, evidence_id, prov:wasDerivedFrom, parseError.
Do not create, alter, or regenerate ontology classes or properties at runtime.`;

return item;

const item = $input.item.json;
const violations = [];

function requireValue(path, value, shape) {
  if (value === null || value === undefined || value === '') {
    violations.push({ shape, path, message: `${path} is required by ontology/cpl-shapes.ttl` });
  }
}

if (item.parseError === true) {
  violations.push({ shape: 'cpl:StrictParseShape', path: 'parseError', message: item.error_message || 'Record failed strict parsing' });
}

requireValue('prov:wasDerivedFrom', item['prov:wasDerivedFrom'], 'cpl:AgentActionShape');
requireValue('timestamp', item.timestamp, 'cpl:AgentActionShape');
requireValue('actor.id', item.actor && item.actor.id, 'cpl:AgentShape');
requireValue('tool', item.tool, 'cpl:ToolShape');
requireValue('accessed_data', item.accessed_data, 'cpl:DataEntityShape');
requireValue('evidence_id', item.evidence_id, 'cpl:EvidenceEventShape');
requireValue('raw_payload', item.raw_payload, 'cpl:EvidenceEventShape');
requireValue('ingest_timestamp', item.ingest_timestamp, 'cpl:EvidenceEventShape');

item.validationPassed = violations.length === 0;
item.shaclReport = {
  conforms: item.validationPassed,
  shapesGraph: 'ontology/cpl-shapes.ttl',
  violations
};
item.failed_stage = item.validationPassed ? null : (item.parseError ? item.failed_stage || 'json_parse' : 'shacl_validation');

return item;
